SELECT f.kind || ' · ' || f.name FROM code_fact f WHERE f.project_id = $1 AND f.kind IN ('migration-file', 'migration-table', 'domain-check', 'contract-schema') UNION ALL SELECT 'таблица модели · ' || t.name FROM project_db_tables t WHERE t.project_id = $1 UNION ALL SELECT 'датчик «migration-file» ' || fact_gap($1, 'migration-file') || ': есть ли миграции SQL — не установлено' WHERE NOT fact_fresh($1, 'migration-file') UNION ALL SELECT 'пересборка набора не прошла: таблицы модели не установлены' WHERE NOT EXISTS (SELECT 1 FROM reproject_state r WHERE r.project_id = $1 AND r.ok)
